SELECT District FROM shop WHERE Number_products < 3000
INTERSECT
SELECT District FROM shop WHERE Number_products > 10000;

SELECT CountryId, CountryName
FROM countries
WHERE CountryId IN (
  SELECT Country FROM car_makers GROUP BY Country HAVING COUNT(*) > 3
)
OR CountryId IN (
  SELECT cm.Country FROM car_makers cm JOIN model_list ml ON ml.Maker = cm.Id WHERE ml.Model = 'fiat'
);

SELECT CountryId, CountryName
FROM countries
WHERE CountryId IN (
    SELECT Country FROM car_makers GROUP BY Country HAVING COUNT(*) > 3
)
OR CountryId IN (
    SELECT cm.Country FROM car_makers cm JOIN model_list ml ON ml.Maker = cm.Id WHERE ml.Model = 'fiat'
